"use strict";
/*
 * Cube 2Dキャラ（C案：深緑髪・キューブの髪飾り）の口パク差分
 * フレーム集。原本は ~/workspace/cube_character/ の 1600x1600
 * WebP で、表示サイズ（最大約300 CSS px）に合わせて 640x640 へ
 * 縮小し WebP q82 で再エンコードしたものを base64 data URI で
 * 埋め込んである（GitHub push がテキスト専用のため）。
 * cube_voice.js が音声会話の初回オープン時に遅延読み込みする。
 * キー: base=閉じ口, a/i/u/e/o=母音の口, blink=瞬き（閉じ目）。
 */
(function (global) {
  const CubeCharFrames = {
    base: "data:image/webp;base64,",
    a: "data:image/webp;base64,",
    i: "data:image/webp;base64,",
    u: "data:image/webp;base64,",
    e: "data:image/webp;base64,",
    o: "data:image/webp;base64,",
    blink: "data:image/webp;base64,"
  };
  global.CubeCharFrames = CubeCharFrames;
  if (typeof module !== "undefined" && module.exports) {
    module.exports = CubeCharFrames;
  }
})(typeof window !== "undefined" ? window : globalThis);
